import sympy
from sympy import ZZ, QQ
from sympy.polys.domains import Domain

CONDITION_LABELS = [
    "H_1: R is an integral domain",
    "H_2: p satisfies the divisibility condition (p|ab implies p|a or p|b)",
    "¬Q: The principal ideal generated by p is NOT a prime ideal of R"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness):
    try:
        # The witness can be a tuple (R, p) or just p (defaulting to R = ZZ)
        if isinstance(witness, tuple) and len(witness) == 2:
            R, p = witness
        else:
            R = ZZ
            p = witness
            
        # H1: R is an integral domain
        # In sympy, Domain instances (like ZZ, QQ, etc.) are integral domains
        if not isinstance(R, Domain):
            return [False, False, False]
            
        try:
            p_R = R(p)
        except Exception:
            return [False, False, False]
            
        h1 = True
        
        # Check if p is a unit in R
        p_is_unit = False
        if p_R != R.zero:
            try:
                R.invert(p_R)
                p_is_unit = True
            except Exception:
                p_is_unit = False
                
        # H2: p satisfies the divisibility condition (p|ab implies p|a or p|b)
        # This holds trivially if p is 0 or a unit. Otherwise, it holds if p is prime.
        h2 = False
        if p_R == R.zero:
            h2 = True
        elif p_is_unit:
            h2 = True
        elif R == ZZ:
            h2 = sympy.isprime(abs(int(p_R)))
        else:
            try:
                if hasattr(R, 'is_prime'):
                    h2 = bool(R.is_prime(p_R))
                elif hasattr(p_R, 'is_irreducible'):
                    h2 = bool(p_R.is_irreducible)
            except Exception:
                pass

        # neg_Q: The principal ideal (p) is NOT a prime ideal
        # A prime ideal must be proper. If p is a unit, (p) = R, which is not proper.
        # If p = 0, (0) is prime in an integral domain.
        # If p is a standard prime, (p) is prime.
        if p_is_unit:
            neg_q = True
        elif p_R == R.zero:
            neg_q = False
        elif R == ZZ:
            neg_q = not sympy.isprime(abs(int(p_R)))
        else:
            try:
                if hasattr(R, 'is_prime'):
                    neg_q = not R.is_prime(p_R)
                elif hasattr(p_R, 'is_irreducible'):
                    neg_q = not p_R.is_irreducible
                else:
                    neg_q = True
            except Exception:
                neg_q = True
                
        return [h1, h2, neg_q]
    except Exception:
        return [False, False, False]